-- Catalog 78 schema from v0.9.33 (ab32e451e70a124e5e77091c4afbb4a3c195ad94).
-- Historical declarations are retained to exercise real old layouts independently of current initialization.

CREATE TABLE runtime_meta(id INTEGER PRIMARY KEY CHECK(id=1),epoch INTEGER NOT NULL);
INSERT INTO runtime_meta VALUES(1,0);
CREATE TABLE threads(id TEXT PRIMARY KEY,agent_code TEXT NOT NULL UNIQUE,title TEXT NOT NULL DEFAULT 'New thread',title_initialized INTEGER NOT NULL DEFAULT 0 CHECK(title_initialized IN (0,1)),revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),created_at_ms INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000),updated_at_ms INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)*1000),pinned INTEGER NOT NULL DEFAULT 0 CHECK(pinned IN (0,1)),archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)),deleted_at_ms INTEGER,activity_cursor INTEGER NOT NULL DEFAULT 0 CHECK(activity_cursor>=0),read_cursor INTEGER NOT NULL DEFAULT 0 CHECK(read_cursor>=0));
CREATE TABLE retired_agent_codes(code TEXT PRIMARY KEY);
CREATE TRIGGER retire_agent_code BEFORE DELETE ON threads BEGIN INSERT INTO retired_agent_codes(code) VALUES(old.agent_code); END;
CREATE TABLE branches(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES threads(id),head TEXT,active_run TEXT);
CREATE INDEX branches_thread ON branches(thread_id);
CREATE TABLE history(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES threads(id),parent TEXT REFERENCES history(id),run_id TEXT NOT NULL REFERENCES runs(id) DEFERRABLE INITIALLY DEFERRED,body TEXT NOT NULL);
CREATE INDEX history_run ON history(run_id);
CREATE TABLE runs(id TEXT PRIMARY KEY,branch_id TEXT REFERENCES branches(id),body TEXT NOT NULL,context_checkpoint_id TEXT REFERENCES context_checkpoints(id));
CREATE INDEX runs_branch ON runs(branch_id);
CREATE INDEX runs_waiting ON runs(json_extract(body,'$.waiting_on')) WHERE json_extract(body,'$.state')='waiting';
CREATE TABLE commands(id TEXT PRIMARY KEY,intent TEXT NOT NULL,receipt TEXT NOT NULL);
CREATE TABLE operations(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),body TEXT NOT NULL);
CREATE UNIQUE INDEX mcp_task_subject ON operations(json_extract(body,'$.host_job.binding.subject.endpoint.resourceKey'),json_extract(body,'$.host_job.binding.subject.endpoint.configurationVersion'),json_extract(body,'$.host_job.binding.subject.endpoint.credentialVersion'),json_extract(body,'$.host_job.mcpTask.task.taskId')) WHERE json_extract(body,'$.host_job.mcpTask') IS NOT NULL;
CREATE UNIQUE INDEX host_job_subject ON operations(json_extract(body,'$.host_job.binding.domain'),json_extract(body,'$.host_job.binding.subject.workspaceId'),json_extract(body,'$.host_job.binding.subject.subjectId')) WHERE json_extract(body,'$.host_job') IS NOT NULL;
CREATE INDEX operations_run ON operations(run_id);
CREATE TABLE computer_requests(id TEXT PRIMARY KEY,requester_run_id TEXT NOT NULL REFERENCES runs(id),root_thread_id TEXT NOT NULL REFERENCES threads(id),root_branch_id TEXT NOT NULL REFERENCES branches(id),body TEXT NOT NULL);
CREATE INDEX computer_requests_root ON computer_requests(root_thread_id,root_branch_id);
CREATE INDEX computer_requests_run ON computer_requests(requester_run_id);
CREATE TABLE model_steps(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),node_id TEXT CHECK(node_id IS NULL OR length(node_id)>0),state TEXT NOT NULL,body TEXT NOT NULL,FOREIGN KEY(run_id,node_id) REFERENCES context_job_nodes(run_id,node_id));
CREATE INDEX model_steps_run ON model_steps(run_id,state);
CREATE TABLE model_selections(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),revision INTEGER NOT NULL,status TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 0,body TEXT NOT NULL,UNIQUE(run_id,revision));
CREATE UNIQUE INDEX model_selections_active ON model_selections(run_id) WHERE active=1;
CREATE UNIQUE INDEX model_steps_active ON model_steps(run_id,coalesce(node_id,'')) WHERE state IN ('prepared','dispatched');
CREATE TABLE model_outputs(request_id TEXT PRIMARY KEY REFERENCES model_steps(id),body TEXT NOT NULL);
CREATE TABLE tool_calls(request_id TEXT NOT NULL REFERENCES model_steps(id),call_id TEXT NOT NULL,body TEXT NOT NULL,receipt TEXT,committed INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(request_id,call_id));
CREATE TABLE policy_checkpoints(run_id TEXT PRIMARY KEY REFERENCES runs(id),identity TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('decision','activation')),state_ref TEXT NOT NULL,pending_state_ref TEXT,action_ref TEXT,continuation_ref TEXT,activation_cursor INTEGER,pending INTEGER NOT NULL,wait_id TEXT,CHECK((pending=1 AND pending_state_ref IS NOT NULL) OR (pending=0 AND pending_state_ref IS NULL)),CHECK((kind='decision' AND action_ref IS NOT NULL) OR (kind='activation' AND action_ref IS NULL AND pending=0)));
CREATE TABLE policy_selections(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),generation INTEGER NOT NULL,status TEXT NOT NULL,body TEXT NOT NULL,UNIQUE(run_id,generation));
CREATE TABLE policy_graph_nodes(action_id TEXT NOT NULL REFERENCES operations(id),node_id TEXT NOT NULL,call_id TEXT NOT NULL,position INTEGER NOT NULL,call TEXT NOT NULL,receipt TEXT,outcome TEXT,PRIMARY KEY(action_id,node_id),UNIQUE(action_id,call_id),UNIQUE(action_id,position));
CREATE TABLE policy_graph_dependencies(action_id TEXT NOT NULL,node_id TEXT NOT NULL,dependency_id TEXT NOT NULL,PRIMARY KEY(action_id,node_id,dependency_id),FOREIGN KEY(action_id,node_id) REFERENCES policy_graph_nodes(action_id,node_id),FOREIGN KEY(action_id,dependency_id) REFERENCES policy_graph_nodes(action_id,node_id));
CREATE TABLE events(cursor INTEGER PRIMARY KEY AUTOINCREMENT,subject TEXT NOT NULL,revision INTEGER NOT NULL,kind TEXT NOT NULL,data TEXT NOT NULL);
CREATE INDEX events_condition ON events(subject,kind,cursor);
CREATE TABLE waits(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),body TEXT NOT NULL);
CREATE TABLE resumptions(wait_id TEXT PRIMARY KEY REFERENCES waits(id),run_id TEXT NOT NULL REFERENCES runs(id),trigger_cursor INTEGER NOT NULL REFERENCES events(cursor),claimed INTEGER NOT NULL,acknowledged INTEGER NOT NULL DEFAULT 0);
CREATE TABLE deliveries(observer TEXT NOT NULL,fact_cursor INTEGER NOT NULL REFERENCES events(cursor),request TEXT NOT NULL,state TEXT NOT NULL,PRIMARY KEY(observer,fact_cursor,request));

CREATE TABLE input_history_content(input_id TEXT PRIMARY KEY REFERENCES input_queue(id),body TEXT NOT NULL);
CREATE TABLE runtime_content_format(id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL); INSERT INTO runtime_content_format VALUES(1,4);
CREATE TABLE resource_occupancy (operation_id TEXT PRIMARY KEY REFERENCES operations(id), claims TEXT NOT NULL);
CREATE TABLE runtime_domains(name TEXT PRIMARY KEY,version INTEGER NOT NULL);
CREATE TABLE input_queue(id TEXT PRIMARY KEY,branch_id TEXT NOT NULL REFERENCES branches(id),run_id TEXT REFERENCES runs(id),mode TEXT NOT NULL,state TEXT NOT NULL,cursor INTEGER NOT NULL,origin TEXT NOT NULL,activation TEXT NOT NULL,sender_thread_id TEXT,sender_branch_id TEXT,body TEXT NOT NULL); CREATE INDEX input_queue_pending ON input_queue(branch_id,state,activation,cursor); CREATE INDEX input_queue_outgoing ON input_queue(sender_thread_id,sender_branch_id,cursor); INSERT INTO runtime_domains(name,version) VALUES('input_queue',8);
CREATE TABLE run_launches(id TEXT PRIMARY KEY REFERENCES runs(id),body TEXT NOT NULL); INSERT INTO runtime_domains(name,version) VALUES('run_launches',3);
CREATE TABLE memory_states(branch_id TEXT PRIMARY KEY REFERENCES branches(id),body TEXT NOT NULL); CREATE TABLE context_checkpoints(id TEXT PRIMARY KEY,branch_id TEXT NOT NULL REFERENCES branches(id),revision INTEGER NOT NULL,through_id TEXT REFERENCES history(id),body TEXT NOT NULL,project_id TEXT,scope TEXT,UNIQUE(branch_id,revision)); CREATE TABLE active_contexts(branch_id TEXT PRIMARY KEY REFERENCES branches(id),checkpoint_id TEXT NOT NULL REFERENCES context_checkpoints(id)); INSERT INTO runtime_domains(name,version) VALUES('context_checkpoints',5);
CREATE TABLE context_jobs(run_id TEXT PRIMARY KEY REFERENCES runs(id),job_key TEXT NOT NULL UNIQUE,branch_id TEXT NOT NULL REFERENCES branches(id),through_id TEXT NOT NULL REFERENCES history(id),expected_revision INTEGER NOT NULL,owner_run_id TEXT REFERENCES runs(id),recipe TEXT NOT NULL,plan_hash TEXT NOT NULL); CREATE INDEX context_jobs_branch ON context_jobs(branch_id); CREATE INDEX context_jobs_owner ON context_jobs(owner_run_id,expected_revision); CREATE TABLE context_job_nodes(run_id TEXT NOT NULL REFERENCES context_jobs(run_id),node_id TEXT NOT NULL,node_index INTEGER NOT NULL,dependencies TEXT NOT NULL,PRIMARY KEY(run_id,node_id),UNIQUE(run_id,node_index)); CREATE TABLE context_job_steps(request_id TEXT PRIMARY KEY REFERENCES model_steps(id),run_id TEXT NOT NULL,node_id TEXT NOT NULL,plan_hash TEXT NOT NULL,is_final INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(run_id,node_id) REFERENCES context_job_nodes(run_id,node_id));
CREATE TABLE child_tasks(id TEXT PRIMARY KEY REFERENCES operations(id),child_thread_id TEXT NOT NULL UNIQUE REFERENCES threads(id),body TEXT NOT NULL); CREATE INDEX child_tasks_parent ON child_tasks(json_extract(body,'$.parent_thread_id')); CREATE TABLE delegated_executions(id TEXT PRIMARY KEY,child_operation_id TEXT NOT NULL REFERENCES child_tasks(id),command_key TEXT UNIQUE,run_id TEXT UNIQUE REFERENCES runs(id),body TEXT NOT NULL); CREATE INDEX delegated_executions_child ON delegated_executions(child_operation_id); CREATE TABLE child_result_files(execution_id TEXT NOT NULL REFERENCES delegated_executions(id) ON DELETE CASCADE,path TEXT NOT NULL,PRIMARY KEY(execution_id,path)); CREATE INDEX child_result_files_path ON child_result_files(path,execution_id); INSERT INTO runtime_domains(name,version) VALUES('collaboration',9);
CREATE TABLE code_exchange_peers(operation_id TEXT PRIMARY KEY REFERENCES operations(id) ON DELETE CASCADE,peer_thread_id TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE); CREATE INDEX code_exchange_peers_thread ON code_exchange_peers(peer_thread_id,operation_id);
CREATE TABLE followups(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES threads(id),source_run_id TEXT NOT NULL REFERENCES runs(id),body TEXT NOT NULL);
      CREATE INDEX followups_thread ON followups(thread_id);
      CREATE INDEX followups_source ON followups(source_run_id);
      CREATE INDEX followups_wait_state ON followups(json_extract(body,'$.wait.state'));
      CREATE TABLE followup_occurrences(id TEXT PRIMARY KEY,followup_id TEXT NOT NULL REFERENCES followups(id),accepted_cursor INTEGER NOT NULL, input_id TEXT UNIQUE REFERENCES input_queue(id),body TEXT NOT NULL);
      CREATE INDEX followup_occurrences_order ON followup_occurrences(followup_id,accepted_cursor);
      CREATE INDEX followup_occurrences_unprepared ON followup_occurrences(followup_id,accepted_cursor) WHERE input_id IS NULL;
      CREATE INDEX followup_inputs_pending ON input_queue(json_extract(body,'$.origin.followup_id'),state) WHERE origin='followup';
      CREATE INDEX followup_source_edges ON events(subject,json_extract(data,'$.generation'),json_extract(data,'$.source_index'),cursor) WHERE kind='followup.source_observed';
      CREATE INDEX followup_research_edges ON events(subject,json_extract(data,'$.generation'),json_extract(data,'$.source_index'),json_extract(data,'$.entity'),json_extract(data,'$.domain_revision')) WHERE kind='followup.source_observed';
CREATE TABLE calendar_projects(id TEXT PRIMARY KEY,body TEXT NOT NULL);
        CREATE TABLE calendar_definitions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES calendar_projects(id),task_id TEXT NOT NULL,body TEXT NOT NULL,UNIQUE(project_id,task_id));
        CREATE TABLE calendar_occurrences(id TEXT PRIMARY KEY,definition_id TEXT NOT NULL REFERENCES calendar_definitions(id),thread_id TEXT NOT NULL REFERENCES threads(id),input_id TEXT UNIQUE REFERENCES input_queue(id),body TEXT NOT NULL);
        CREATE INDEX calendar_occurrences_definition ON calendar_occurrences(definition_id);
CREATE TABLE goals(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES threads(id),branch_id TEXT NOT NULL REFERENCES branches(id),body TEXT NOT NULL);
        CREATE INDEX goals_thread ON goals(thread_id); CREATE INDEX goals_branch ON goals(branch_id);
        CREATE TABLE goal_runs(id TEXT PRIMARY KEY REFERENCES runs(id),goal_id TEXT NOT NULL REFERENCES goals(id),primary_run INTEGER NOT NULL);
        CREATE INDEX goal_runs_goal ON goal_runs(goal_id);
        CREATE TABLE goal_children(id TEXT PRIMARY KEY REFERENCES child_tasks(id),goal_id TEXT NOT NULL REFERENCES goals(id));
        CREATE TABLE goal_usage(id TEXT PRIMARY KEY REFERENCES goals(id),body TEXT NOT NULL);
CREATE TABLE mcp_interactions(id TEXT PRIMARY KEY,operation_id TEXT NOT NULL REFERENCES operations(id),connection_id TEXT NOT NULL,request_key TEXT NOT NULL,body TEXT NOT NULL,UNIQUE(connection_id,request_key)); CREATE INDEX mcp_interactions_operation ON mcp_interactions(operation_id);
CREATE TABLE bot_thread_bindings(thread_id TEXT PRIMARY KEY REFERENCES threads(id),bot_id TEXT NOT NULL);
        CREATE INDEX bot_thread_bindings_bot ON bot_thread_bindings(bot_id);
        CREATE TABLE bot_execution_gates(bot_id TEXT PRIMARY KEY,profile_revision INTEGER NOT NULL,kernel_epoch INTEGER NOT NULL,body TEXT NOT NULL);
        CREATE TABLE bot_run_holds(run_id TEXT PRIMARY KEY REFERENCES runs(id),bot_id TEXT NOT NULL,activity_operation_id TEXT NOT NULL);
        CREATE INDEX bot_run_holds_scope ON bot_run_holds(bot_id,activity_operation_id);
        CREATE INDEX bot_memory_scope ON operations(json_extract(body,'$.intent.kind'),json_extract(body,'$.intent.scopeId'));
        CREATE INDEX bot_child_parent ON child_tasks(json_extract(body,'$.parent_thread_id'));
PRAGMA user_version=78;
